ALTER TABLE products ADD COLUMN IF NOT EXISTS price_inr numeric(10,2) DEFAULT NULL, ADD COLUMN IF NOT EXISTS price_cad numeric(10,2) DEFAULT NULL, ADD COLUMN IF NOT EXISTS price_aud numeric(10,2) DEFAULT NULL, ADD COLUMN IF NOT EXISTS price_nzd numeric(10,2) DEFAULT NULL, ADD COLUMN IF NOT EXISTS price_usd numeric(10,2) DEFAULT NULL, ADD COLUMN IF NOT EXISTS sale_price_inr numeric(10,2) DEFAULT NULL, ADD COLUMN IF NOT EXISTS sale_price_cad numeric(10,2) DEFAULT NULL, ADD COLUMN IF NOT EXISTS sale_price_aud numeric(10,2) DEFAULT NULL, ADD COLUMN IF NOT EXISTS sale_price_nzd numeric(10,2) DEFAULT NULL, ADD COLUMN IF NOT EXISTS sale_price_usd numeric(10,2) DEFAULT NULL;
UPDATE products SET price_inr = price WHERE price_inr IS NULL AND price IS NOT NULL;
UPDATE products SET sale_price_inr = sale_price WHERE sale_price_inr IS NULL AND sale_price IS NOT NULL;